class ProductBarcode < ApplicationRecord
  # Functional taxonomy: what the barcode is USED for, not its format.
  # manufacturer — assigned by GS1 / the product manufacturer (EAN, UPC, etc.)
  # internal     — generated by WorkPulse for products without a manufacturer code
  # carton       — barcode on the outer carton or shipping box
  BARCODE_TYPES = %w[manufacturer internal carton].freeze

  belongs_to :business
  belongs_to :product

  validates :barcode,      presence: true, length: { maximum: 100 }
  validates :barcode_type, inclusion: { in: BARCODE_TYPES }, allow_blank: false
  validates :barcode,      uniqueness: { scope: :business_id, case_sensitive: false }

  before_validation :set_business_id
  before_validation :normalize_barcode
  before_validation :infer_barcode_type  # runs before inclusion check so nil type gets set

  # When a barcode is explicitly marked primary (outside of a product form save),
  # demote all other barcodes for the same product.
  after_save :demote_siblings, if: :is_primary?

  scope :primary, -> { where(is_primary: true) }
  scope :ordered, -> { order(is_primary: :desc, created_at: :asc) }

  private

  def set_business_id
    self.business_id ||= product&.business_id
  end

  def normalize_barcode
    self.barcode = barcode.to_s.strip.presence
  end

  def infer_barcode_type
    return if barcode.blank? || barcode_type.present?
    # Default to manufacturer for hand-entered or scanned barcodes.
    # Internal barcodes are only created via BarcodeGenerator which sets the type
    # explicitly, so they never reach this fallback.
    self.barcode_type = "manufacturer"
  end

  def demote_siblings
    product.product_barcodes.where.not(id: id).update_all(is_primary: false)
  end
end
